<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('activities.view');
$pageTitle=t('activities');$pdo=db();$type=(string)($_GET['type']??'');$status=(string)($_GET['status']??'pending');$assigned=(int)($_GET['assigned_to']??0);$q=trim((string)($_GET['q']??''));
$where=['1=1'];$params=[];if(in_array($type,['task','event','call','email','meeting','note'],true)){$where[]='a.activity_type=?';$params[]=$type;}if(in_array($status,['pending','completed','cancelled'],true)){$where[]='a.status=?';$params[]=$status;}elseif($status==='overdue'){$where[]="a.status='pending' AND a.due_at<NOW()";}if($assigned>0){$where[]='a.assigned_to=?';$params[]=$assigned;}if($q!==''){$where[]='(a.subject LIKE ? OR a.details LIKE ? OR c.company_name LIKE ? OR CONCAT(ct.first_name,\' \',ct.last_name) LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term,$term);}
$sql="SELECT a.*,c.company_name,ct.first_name,ct.last_name,d.title deal_title,u.name assigned_name FROM activities a LEFT JOIN clients c ON c.id=a.client_id LEFT JOIN contacts ct ON ct.id=a.contact_id LEFT JOIN deals d ON d.id=a.deal_id LEFT JOIN users u ON u.id=a.assigned_to WHERE ".implode(' AND ',$where)." ORDER BY CASE WHEN a.status='pending' THEN 0 ELSE 1 END,COALESCE(a.due_at,a.created_at) ASC LIMIT 300";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'&&has_permission('activities.manage')){verify_csrf();$id=(int)($_POST['id']??0);$new=(string)($_POST['status']??'completed');if($id&&in_array($new,['pending','completed','cancelled'],true)){db()->prepare('UPDATE activities SET status=?,completed_at=? WHERE id=?')->execute([$new,$new==='completed'?date('Y-m-d H:i:s'):null,$id]);flash('success','Actividad actualizada.');redirect('activities.php?status='.urlencode($status));}}
require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Tareas, eventos, llamadas y correos</h2><span class="table-sub">La línea de tiempo operativa de cada cliente, contacto y negocio.</span></div><?php if(has_permission('activities.manage')):?><a class="btn btn-primary btn-small" href="activity_form.php">+ CREAR ACTIVIDAD</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>"></label><label>Tipo<select name="type"><option value="">Todos</option><?php foreach(['task','event','call','email','meeting','note']as$x):?><option value="<?=$x?>" <?=$type===$x?'selected':''?>><?=e(crm_activity_type_label($x))?></option><?php endforeach;?></select></label><label>Estado<select name="status"><option value="">Todos</option><option value="pending" <?=$status==='pending'?'selected':''?>>Pendientes</option><option value="overdue" <?=$status==='overdue'?'selected':''?>>Atrasadas</option><option value="completed" <?=$status==='completed'?'selected':''?>>Completadas</option><option value="cancelled" <?=$status==='cancelled'?'selected':''?>>Canceladas</option></select></label><label>Asignado a<select name="assigned_to"><option value="0">Todos</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$assigned===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay actividades.</div><?php else:?><table class="data-table"><thead><tr><th>Actividad</th><th>Cliente / contacto</th><th>Negocio</th><th>Fecha</th><th>Asignado</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as$row):$over=$row['status']==='pending'&&$row['due_at']&&strtotime($row['due_at'])<time();?><tr><td><strong><?=e($row['subject'])?></strong><span class="table-sub"><?=e(crm_activity_type_label($row['activity_type']))?> · <?=e(ucfirst($row['priority']))?></span></td><td><?=e($row['company_name']?:trim($row['first_name'].' '.$row['last_name'])?:'—')?></td><td><?=e($row['deal_title']?:'—')?></td><td><?=$row['due_at']?e((new DateTimeImmutable($row['due_at']))->format('d/m/Y H:i')):'Sin fecha'?><?php if($over):?><span class="table-sub" style="color:var(--red)">Atrasada</span><?php endif;?></td><td><?=e($row['assigned_name']?:'Sin asignar')?></td><td><span class="badge badge-<?=$row['status']==='completed'?'green':($row['status']==='cancelled'?'gray':($over?'red':'orange'))?>"><?=e($row['status'])?></span></td><td><div class="actions"><?php if(has_permission('activities.manage')):?><a class="btn btn-light btn-small" href="activity_form.php?id=<?=$row['id']?>">Editar</a><?php if($row['status']!=='completed'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="status" value="completed"><button class="btn btn-success btn-small">Completar</button></form><?php endif;?><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
